  function addSym(cat, items) {
    var g = SYMPTOMS.find(function (x) { return x.cat === cat; });
    if (!g) { g = { cat: cat, items: [] }; SYMPTOMS.push(g); }
    items.forEach(function (i) { if (!g.items.some(function (y) { return y[0] === i[0]; })) g.items.push(i); });
  }
